import streamlit as st
import pandas as pd
import numpy as np
#Displaying multiple tabs on the same page
tab1, tab2, tab3 = st.tabs(["Movie Images", "Movie Names", "Movie Ratings"])
with tab1:
    st.header("Movie Images")
    st.write("This tab displays images of movies.")
with tab2:
    st.header("Movie Names")
    st.write("This tab displays names of movies.")
    a=pd.read_csv("movies.csv")
    
with tab3:
    st.header("Movie Ratings")
    st.write("This tab displays ratings of movies.")
#Recommendation system for movies based on genre, ratings, and popularity
    genre = st.selectbox("Select Genre", a['genres'].unique())
    rating = st.slider("Select Rating", 0.0, 10.0, 0.1)
    popularity = st.slider("Select Popularity", 0, 100, 1)  
    if genre and rating and popularity:
        filtered_movies = a[(a['genres'] == genre)]
        st.write("Recommended Movies:")
        st.dataframe(filtered_movies)
with tab2:
    st.header("Movie Names")
    st.write("This tab displays names of movies.")
    a=pd.read_csv("movies.csv")
    b=pd.read_csv("BollywoodMovieDetail.csv")
#Joining Both Dataset a and b
    c=pd.merge(a, b, on='title', how='outer')
    st.dataframe(c)
    st.write(len(c))
   
